9115],[-111.62284,43.59112]]},{"type":"LineString","coordinates":[[-111.52505,43.60962],[-111.52557,43.60993],[-111.52861,43.61189],[-111.53062,43.61402],[-111.53088,43.61421]]}]}$geojson$;
  v_npts     int;
  v_max_lat  float;
  v_min_lat  float;
  v_max_lon  float;
  v_min_lon  float;
  v_centroid_lat float;
  v_centroid_lon float;
BEGIN
  SELECT id INTO v_river_id FROM public.rivers WHERE slug = 'sf-snake-palisades';
  IF v_river_id IS NULL THEN
    RAISE EXCEPTION 'River sf-snake-palisades not found';
  END IF;

  -- Replace geometry with new Swan Valley corridor fetch
  UPDATE public.river_geometries
  SET
    geom       = ST_Multi(ST_CollectionExtract(ST_GeomFromGeoJSON(v_geojson), 2)),
    updated_at = now()
  WHERE river_id = v_river_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'No river_geometries row found for sf-snake-palisades';
  END IF;

  -- Verify
  SELECT
    ST_NPoints(geom),
    ST_YMax(geom),
    ST_YMin(geom),
    ST_XMax(geom),
    ST_XMin(geom),
    ST_Y(ST_Centroid(geom)),
    ST_X(ST_Centroid(geom))
  INTO v_npts, v_max_lat, v_min_lat, v_max_lon, v_min_lon, v_centroid_lat, v_centroid_lon
  FROM public.river_geometries
  WHERE river_id = v_river_id;

  RAISE NOTICE 'SF Snake after fix: % pts, lat %–%, lon %–%, centroid (%, %)',
    v_npts,
    round(v_min_lat::numeric, 4), round(v_max_lat::numeric, 4),
    round(v_min_lon::numeric, 4), round(v_max_lon::numeric, 4),
    round(v_centroid_lat::numeric, 4), round(v_centroid_lon::numeric, 4);

  -- Guard: centroid must be in Swan Valley corridor
  IF v_centroid_lat < 43.3 OR v_centroid_lat > 43.6 THEN
    RAISE EXCEPTION 'Centroid lat=% outside Swan Valley range 43.3–43.6', v_centroid_lat;
  END IF;
  IF v_centroid_lon < -111.75 OR v_centroid_lon > -111.15 THEN
    RAISE EXCEPTION 'Centroid lon=% outside Swan Valley range -111.75–-111.15', v_centroid_lon;
  END IF;
  -- Guard: must not extend into Rigby/Rexburg agricultural flatlands
  IF v_max_lat > 43.68 THEN
    RAISE EXCEPTION 'max_lat=% still in flatlands area (> 43.68)', v_max_lat;
  END IF;
  IF v_min_lon < -111.80 THEN
    RAISE EXCEPTION 'min_lon=% still extends past Henry Fork confluence (-111.80)', v_min_lon;
  END IF;
END;
$$;
